var characterReplacement = function(s, k) {
    let n = s.length;
    let start = 0;
    let end = 0;
    
    let subStr = [];
    let dict = {};

    let longestRepeat = 0;
    for (end=0; end<n; end++)
    {
        //console.log('FIRST SUB = ',subStr);
        subStr.push(s[end]);
        if (!(s[end] in dict))
        {
            dict[s[end]] = 1;
        }
        else
        {
            dict[s[end]] = dict[s[end]] + 1;
        }

        //let window_length = subStr.length;
        //let maxFrequency = Math.max(...Object.values(dict));
        //console.log('sub str = ',subStr);
        //console.log('dict = ',dict);
        //console.log("win len =",window_length)
        //console.log('max fre =',maxFrequency)


        while(subStr.length-Math.max(...Object.values(dict)) > k)
        {
            let removeChar = s[start];
            subStr = [...s.slice(start+1, end+1)];
            start++;
            //console.log('after removal = ',subStr);

            dict[removeChar] = dict[removeChar] - 1;
            if (dict[removeChar] == 0)
            {
                delete dict[removeChar];
            }
            //console.log('dict aftere remova = ',dict);
            //window_length = subStr.length;
            //maxFrequency = Math.max(...Object.values(dict));

        }
        longestRepeat = Math.max(longestRepeat, subStr.length);
    }
    return longestRepeat;


};

let s = "";
let k = 2;

let result = characterReplacement(s,k);
console.log(result);